1	import { mesDe, mesValido, somarMeses } from './date';
2	import { falha, ok, type AppState, type Categoria, type Centavos, type Mes, type Resultado, type Transacao } from './types';
3	
4	export type EstadoOrcamento = 'normal' | 'atencao' | 'estourado';
5	
6	/** Abaixo de 80% é normal, de 80% a 100% é atenção, acima de 100% é estourado. */
7	export function estadoDoConsumo(gasto: Centavos, limite: Centavos): EstadoOrcamento {
8	  if (limite === 0) return gasto > 0 ? 'estourado' : 'normal';
9	  if (gasto > limite) return 'estourado';
10	  if (gasto * 100 >= limite * 80) return 'atencao';
11	  return 'normal';
12	}
13	
14	/** Percentual consumido (inteiro); null quando o limite é zero. */
15	export function percentualConsumido(gasto: Centavos, limite: Centavos): number | null {
16	  return limite === 0 ? null : Math.round((gasto * 100) / limite);
17	}
18	
19	/** Soma das despesas por categoria dentro do mês, em todas as contas. */
20	export function gastoPorCategoria(transacoes: Transacao[], mes: Mes): Map<string, Centavos> {
21	  const gastos = new Map<string, Centavos>();
22	  for (const t of transacoes) {
23	    if (t.tipo !== 'despesa' || mesDe(t.data) !== mes) continue;
24	    gastos.set(t.categoriaId, (gastos.get(t.categoriaId) ?? 0) + t.valor);
25	  }
26	  return gastos;
27	}
28	
29	export interface LinhaOrcamento {
30	  categoria: Categoria;
31	  limite: Centavos | null;
32	  gasto: Centavos;
33	  restante: Centavos | null;
34	  percentual: number | null;
35	  estado: EstadoOrcamento | null;
36	}
37	
38	export function linhasOrcamento(estado: AppState, mes: Mes): LinhaOrcamento[] {
39	  const gastos = gastoPorCategoria(estado.transacoes, mes);
40	  const limites = new Map(estado.orcamentos.filter((o) => o.mes === mes).map((o) => [o.categoriaId, o.limite]));
41	  return estado.categorias
42	    .filter((c) => c.tipo === 'despesa' && (!c.arquivada || limites.has(c.id) || (gastos.get(c.id) ?? 0) > 0))
43	    .map((categoria): LinhaOrcamento => {
44	      const limite = limites.get(categoria.id) ?? null;
45	      const gasto = gastos.get(categoria.id) ?? 0;
46	      return {
47	        categoria,
48	        limite,
49	        gasto,
50	        restante: limite === null ? null : limite - gasto,
51	        percentual: limite === null ? null : percentualConsumido(gasto, limite),
52	        estado: limite === null ? null : estadoDoConsumo(gasto, limite),
53	      };
54	    })
55	    .sort((a, b) => a.categoria.nome.localeCompare(b.categoria.nome, 'pt-BR'));
56	}
57	
58	export interface TotaisOrcamento {
59	  limites: Centavos;
60	  gastoComLimite: Centavos;
61	  gastoSemOrcamento: Centavos;
62	}
63	
64	export function totaisOrcamento(linhas: LinhaOrcamento[]): TotaisOrcamento {
65	  let limites = 0;
66	  let gastoComLimite = 0;
67	  let gastoSemOrcamento = 0;
68	  for (const l of linhas) {
69	    if (l.limite === null) gastoSemOrcamento += l.gasto;
70	    else {
71	      limites += l.limite;
72	      gastoComLimite += l.gasto;
73	    }
74	  }
75	  return { limites, gastoComLimite, gastoSemOrcamento };
76	}
77	
78	export function definirLimite(estado: AppState, categoriaId: string, mes: Mes, limite: Centavos): Resultado<AppState> {
79	  if (!mesValido(mes)) return falha('Mês inválido.');
80	  if (!Number.isInteger(limite) || limite < 0) return falha('O limite não pode ser negativo.', 'limite');
81	  const categoria = estado.categorias.find((c) => c.id === categoriaId);
82	  if (!categoria || categoria.tipo !== 'despesa') return falha('Escolha uma categoria de despesa.');
83	  const resto = estado.orcamentos.filter((o) => !(o.categoriaId === categoriaId && o.mes === mes));
84	  return ok({ ...estado, orcamentos: [...resto, { categoriaId, mes, limite }] });
85	}
86	
87	export function removerLimite(estado: AppState, categoriaId: string, mes: Mes): Resultado<AppState> {
88	  return ok({ ...estado, orcamentos: estado.orcamentos.filter((o) => !(o.categoriaId === categoriaId && o.mes === mes)) });
89	}
90	
91	export function mesTemLimites(estado: AppState, mes: Mes): boolean {
92	  return estado.orcamentos.some((o) => o.mes === mes);
93	}
94	
95	/** Copia os limites do mês anterior sem sobrescrever limites que já existam no mês. */
96	export function copiarMesAnterior(estado: AppState, mes: Mes): Resultado<AppState> {
97	  const anterior = somarMeses(mes, -1);
98	  const origem = estado.orcamentos.filter((o) => o.mes === anterior);
99	  if (origem.length === 0) return falha('O mês anterior não tem limites para copiar.');
100	  const existentes = new Set(estado.orcamentos.filter((o) => o.mes === mes).map((o) => o.categoriaId));
101	  const novos = origem.filter((o) => !existentes.has(o.categoriaId)).map((o) => ({ ...o, mes }));
102	  return ok({ ...estado, orcamentos: [...estado.orcamentos, ...novos] });
103	}
