1	import { dataValida, diferencaMeses, mesDe, somarMeses } from './date';
2	import { novoId, proximoTempo } from './id';
3	import { falha, ok, type Aporte, type AppState, type Centavos, type DataISO, type Meta, type Resultado } from './types';
4	
5	export const META_NOME_MAX = 40;
6	
7	export interface DadosMeta {
8	  nome: string;
9	  valorAlvo: Centavos;
10	  prazo?: DataISO;
11	}
12	
13	export interface DadosAporte {
14	  data: DataISO;
15	  /** Positivo para aporte, negativo para retirada. */
16	  valor: Centavos;
17	}
18	
19	export function acumulado(meta: Pick<Meta, 'aportes'>): Centavos {
20	  return meta.aportes.reduce((soma, a) => soma + a.valor, 0);
21	}
22	
23	/**
24	 * Reavalia o status a partir dos aportes: concluída quando o acumulado atinge o alvo
25	 * (com a data do aporte que cruzou o alvo pela última vez) e ativa se voltar abaixo.
26	 * Metas arquivadas mantêm o status.
27	 */
28	export function recalcularStatus(meta: Meta): Meta {
29	  if (meta.status === 'arquivada') return meta;
30	  const ordenados = [...meta.aportes].sort((a, b) => (a.data < b.data ? -1 : a.data > b.data ? 1 : 0));
31	  let soma = 0;
32	  let cruzouEm: DataISO | undefined;
33	  for (const aporte of ordenados) {
34	    const antes = soma;
35	    soma += aporte.valor;
36	    if (antes < meta.valorAlvo && soma >= meta.valorAlvo) cruzouEm = aporte.data;
37	  }
38	  if (soma >= meta.valorAlvo) return { ...meta, status: 'concluida', concluidaEm: cruzouEm };
39	  const { concluidaEm: _removido, ...resto } = meta;
40	  void _removido;
41	  return { ...resto, status: 'ativa' };
42	}
43	
44	export function validarDadosMeta(dados: DadosMeta, hoje: DataISO, existente?: Meta): Resultado<DadosMeta> {
45	  const nome = dados.nome.trim();
46	  if (!nome) return falha('Informe o nome da meta.', 'nome');
47	  if (nome.length > META_NOME_MAX) return falha(`O nome deve ter no máximo ${META_NOME_MAX} caracteres.`, 'nome');
48	  if (!Number.isInteger(dados.valorAlvo) || dados.valorAlvo <= 0) return falha('O valor alvo deve ser maior que zero.', 'valorAlvo');
49	  if (dados.prazo !== undefined && dados.prazo !== '') {
50	    if (!dataValida(dados.prazo)) return falha('Informe um prazo válido.', 'prazo');
51	    if (dados.prazo !== existente?.prazo && dados.prazo < hoje) return falha('O prazo não pode ser anterior a hoje.', 'prazo');
52	  }
53	  return ok({ nome, valorAlvo: dados.valorAlvo, prazo: dados.prazo || undefined });
54	}
55	
56	export function criarMeta(estado: AppState, dados: DadosMeta, hoje: DataISO): Resultado<AppState> {
57	  const v = validarDadosMeta(dados, hoje);
58	  if (!v.ok) return v;
59	  const meta: Meta = { id: novoId(), ...v.valor, aportes: [], status: 'ativa', criadaEm: proximoTempo() };
60	  return ok({ ...estado, metas: [...estado.metas, meta] });
61	}
62	
63	function atualizarMeta(estado: AppState, id: string, fn: (meta: Meta) => Resultado<Meta>): Resultado<AppState> {
64	  const meta = estado.metas.find((m) => m.id === id);
65	  if (!meta) return falha('Meta não encontrada.');
66	  const r = fn(meta);
67	  if (!r.ok) return r;
68	  return ok({ ...estado, metas: estado.metas.map((m) => (m.id === id ? r.valor : m)) });
69	}
70	
71	export function editarMeta(estado: AppState, id: string, dados: DadosMeta, hoje: DataISO): Resultado<AppState> {
72	  return atualizarMeta(estado, id, (meta) => {
73	    const v = validarDadosMeta(dados, hoje, meta);
74	    if (!v.ok) return v;
75	    const { prazo: _prazo, ...semPrazo } = meta;
76	    void _prazo;
77	    return ok(recalcularStatus({ ...semPrazo, ...v.valor }));
78	  });
79	}
80	
81	function validarAporte(dados: DadosAporte): Resultado<DadosAporte> {
82	  if (!dataValida(dados.data)) return falha('Informe uma data válida.', 'data');
83	  if (!Number.isInteger(dados.valor) || dados.valor === 0) return falha('O valor deve ser maior que zero.', 'valor');
84	  return ok(dados);
85	}
86	
87	function comAportes(meta: Meta, aportes: Aporte[]): Resultado<Meta> {
88	  const novo = { ...meta, aportes };
89	  if (acumulado(novo) < 0) return falha('A retirada deixaria o valor acumulado negativo.', 'valor');
90	  return ok(recalcularStatus(novo));
91	}
92	
93	export function registrarAporte(estado: AppState, metaId: string, dados: DadosAporte): Resultado<AppState> {
94	  const v = validarAporte(dados);
95	  if (!v.ok) return v;
96	  return atualizarMeta(estado, metaId, (meta) => comAportes(meta, [...meta.aportes, { id: novoId(), ...v.valor }]));
97	}
98	
99	export function editarAporte(estado: AppState, metaId: string, aporteId: string, dados: DadosAporte): Resultado<AppState> {
100	  const v = validarAporte(dados);
101	  if (!v.ok) return v;
102	  return atualizarMeta(estado, metaId, (meta) => {
103	    if (!meta.aportes.some((a) => a.id === aporteId)) return falha('Aporte não encontrado.');
104	    return comAportes(meta, meta.aportes.map((a) => (a.id === aporteId ? { ...a, ...v.valor } : a)));
105	  });
106	}
107	
108	export function excluirAporte(estado: AppState, metaId: string, aporteId: string): Resultado<AppState> {
109	  return atualizarMeta(estado, metaId, (meta) => comAportes(meta, meta.aportes.filter((a) => a.id !== aporteId)));
110	}
111	
112	export function arquivarMeta(estado: AppState, id: string): Resultado<AppState> {
113	  return atualizarMeta(estado, id, (meta) => ok({ ...meta, status: 'arquivada' }));
114	}
115	
116	export function reativarMeta(estado: AppState, id: string): Resultado<AppState> {
117	  return atualizarMeta(estado, id, (meta) => ok(recalcularStatus({ ...meta, status: 'ativa' })));
118	}
119	
120	export type AporteNecessario =
121	  | { tipo: 'sem-prazo' }
122	  | { tipo: 'concluida' }
123	  | { tipo: 'normal'; valor: Centavos; meses: number }
124	  | { tipo: 'ultimo-mes'; valor: Centavos; meses: 1 }
125	  | { tipo: 'vencido'; valor: Centavos; meses: 0 };
126	
127	/** (alvo - acumulado) dividido pelos meses restantes, contando o mês corrente, arredondado para cima. */
128	export function aporteMensalNecessario(meta: Meta, hoje: DataISO): AporteNecessario {
129	  const restante = meta.valorAlvo - acumulado(meta);
130	  if (restante <= 0) return { tipo: 'concluida' };
131	  if (!meta.prazo) return { tipo: 'sem-prazo' };
132	  const meses = diferencaMeses(mesDe(hoje), mesDe(meta.prazo)) + 1;
133	  if (meses < 1) return { tipo: 'vencido', valor: restante, meses: 0 };
134	  if (meses === 1) return { tipo: 'ultimo-mes', valor: restante, meses: 1 };
135	  return { tipo: 'normal', valor: Math.ceil(restante / meses), meses };
136	}
137	
138	/** Média mensal líquida dos aportes nos 3 últimos meses completos; null sem nenhum registro no período. */
139	export function ritmoReal(meta: Meta, hoje: DataISO): Centavos | null {
140	  const atual = mesDe(hoje);
141	  const janela = new Set([1, 2, 3].map((n) => somarMeses(atual, -n)));
142	  const dentro = meta.aportes.filter((a) => janela.has(mesDe(a.data)));
143	  if (dentro.length === 0) return null;
144	  return Math.round(dentro.reduce((s, a) => s + a.valor, 0) / 3);
145	}
146	
147	export type SituacaoRitmo = 'no-ritmo' | 'abaixo-do-ritmo' | 'sem-dados';
148	
149	/** Só se aplica a metas ativas com prazo e valor ainda a juntar. */
150	export function situacaoRitmo(meta: Meta, hoje: DataISO): SituacaoRitmo | null {
151	  const necessario = aporteMensalNecessario(meta, hoje);
152	  if (necessario.tipo === 'sem-prazo' || necessario.tipo === 'concluida') return null;
153	  const ritmo = ritmoReal(meta, hoje);
154	  if (ritmo === null) return 'sem-dados';
155	  return ritmo >= necessario.valor ? 'no-ritmo' : 'abaixo-do-ritmo';
156	}
157	
158	/** Ativas por prazo mais próximo (sem prazo por último), depois as concluídas. */
159	export function ordenarMetas(metas: Meta[]): Meta[] {
160	  const grupo = (m: Meta) => (m.status === 'ativa' ? 0 : m.status === 'concluida' ? 1 : 2);
161	  return [...metas].sort((a, b) => {
162	    if (grupo(a) !== grupo(b)) return grupo(a) - grupo(b);
163	    const pa = a.prazo ?? '9999-99-99';
164	    const pb = b.prazo ?? '9999-99-99';
165	    return pa < pb ? -1 : pa > pb ? 1 : a.nome.localeCompare(b.nome, 'pt-BR');
166	  });
167	}
