28	/** Último dia do ciclo da fatura de `mes` (o dia de fechamento, inclusive). */
29	export function fechamentoFatura(config: CartaoConfig, mes: Mes): DataISO {
30	  return `${mes}-${dia2(config.diaFechamento)}`;
31	}
32	
33	/** Ciclo da fatura de `mes`: do dia seguinte ao fechamento anterior até o fechamento de `mes`. */
34	export function cicloFatura(config: CartaoConfig, mes: Mes): { inicio: DataISO; fim: DataISO } {
35	  const anterior = fechamentoFatura(config, somarMeses(mes, -1));
36	  const [a, m, d] = anterior.split('-').map(Number);
37	  const proximo = new Date(Date.UTC(a, m - 1, d + 1)).toISOString().slice(0, 10);
38	  return { inicio: proximo, fim: fechamentoFatura(config, mes) };
39	}
40	
41	/** Vence no mês do fechamento se o vencimento é depois do fechamento; senão, no mês seguinte. */
42	export function vencimentoFatura(config: CartaoConfig, mes: Mes): DataISO {
43	  const mesVenc = config.diaVencimento > config.diaFechamento ? mes : somarMeses(mes, 1);
44	  return `${mesVenc}-${dia2(config.diaVencimento)}`;
45	}
46	
47	/** Fatura aberta hoje: a que fecha no mês corrente, ou no seguinte se o fechamento já passou. */
48	export function mesFaturaAberta(config: CartaoConfig, hoje: DataISO): Mes {
49	  const dia = Number(hoje.slice(8, 10));
50	  return dia <= config.diaFechamento ? mesDe(hoje) : somarMeses(mesDe(hoje), 1);
51	}
