108	export interface DadosCompraParcelada {
109	  contaId: string;
110	  descricao: string;
111	  valorTotal: Centavos;
112	  parcelas: number;
113	  /** Data da primeira parcela. */
114	  data: DataISO;
115	  categoriaId: string;
116	}
117	
118	/** Divide em centavos exatos: o resto da divisão fica na primeira parcela. */
119	export function dividirParcelas(total: Centavos, parcelas: number): Centavos[] {
120	  const base = Math.floor(total / parcelas);
121	  const resto = total - base * parcelas;
122	  return Array.from({ length: parcelas }, (_, i) => (i === 0 ? base + resto : base));
123	}
124	
125	/** Mesmo dia nos meses seguintes, limitado ao último dia de cada mês. */
126	export function dataDaParcela(primeira: DataISO, indice: number): DataISO {
127	  const mes = somarMeses(mesDe(primeira), indice);
128	  const [ano, m] = mes.split('-').map(Number);
129	  const dia = Math.min(Number(primeira.slice(8, 10)), diasNoMes(ano, m));
130	  return `${mes}-${dia2(dia)}`;
131	}
132	
133	export function criarCompraParcelada(estado: AppState, dados: DadosCompraParcelada): Resultado<AppState> {
134	  const conta = estado.contas.find((c) => c.id === dados.contaId);
135	  if (!conta || conta.tipo !== 'cartao' || conta.arquivada) return falha('Escolha um cartão ativo.', 'contaId');
136	  const descricao = dados.descricao.trim();
137	  if (!descricao) return falha('Informe a descrição da compra.', 'descricao');
138	  if (!Number.isInteger(dados.parcelas) || dados.parcelas < PARCELAS_MIN || dados.parcelas > PARCELAS_MAX) {
139	    return falha(`O número de parcelas deve ficar entre ${PARCELAS_MIN} e ${PARCELAS_MAX}.`, 'parcelas');
140	  }
141	  if (!Number.isInteger(dados.valorTotal) || dados.valorTotal < dados.parcelas) {
142	    return falha('O valor total deve ser de ao menos 1 centavo por parcela.', 'valorTotal');
143	  }
144	  if (!dataValida(dados.data)) return falha('Informe uma data válida.', 'data');
145	  const categoria = estado.categorias.find((c) => c.id === dados.categoriaId);
146	  if (!categoria || categoria.tipo !== 'despesa' || categoria.arquivada) return falha('Escolha uma categoria de despesa ativa.', 'categoriaId');
147	
148	  const grupoId = novoId();
149	  const valores = dividirParcelas(dados.valorTotal, dados.parcelas);
150	  const novas: Transacao[] = valores.map((valor, i) => {
151	    const sufixo = ` (${i + 1}/${dados.parcelas})`;
152	    return {
153	      id: novoId(),
154	      contaId: conta.id,
155	      categoriaId: categoria.id,
156	      tipo: 'despesa',
157	      valor,
158	      data: dataDaParcela(dados.data, i),
159	      descricao: descricao.slice(0, DESCRICAO_MAX - sufixo.length) + sufixo,
160	      criadaEm: proximoTempo(),
161	      parcela: { grupoId, numero: i + 1, total: dados.parcelas },
162	    };
163	  });
164	  return ok({ ...estado, transacoes: [...estado.transacoes, ...novas] });
165	}
