188	export function registrarPagamento(estado: AppState, dados: DadosPagamento, hoje: DataISO): Resultado<AppState> {
189	  const cartao = estado.contas.find((c) => c.id === dados.contaCartaoId);
190	  if (!cartao || cartao.tipo !== 'cartao' || !cartao.cartao) return falha('Cartão não configurado.');
191	  const origem = estado.contas.find((c) => c.id === dados.contaOrigemId);
192	  if (!origem || origem.arquivada || origem.tipo === 'cartao') return falha('Escolha uma conta de origem ativa que não seja cartão.', 'contaOrigemId');
193	  if (!Number.isInteger(dados.valor) || dados.valor <= 0) return falha('O valor deve ser maior que zero.', 'valor');
194	  if (!dataValida(dados.data)) return falha('Informe uma data válida.', 'data');
195	  const resumo = resumoFatura(estado, cartao, dados.mesFatura, hoje);
196	  if (!resumo) return falha('Cartão não configurado.');
197	  if (dados.valor > resumo.restante) return falha('O valor é maior que o restante da fatura.', 'valor');
198	  const pagamento: PagamentoFatura = { id: novoId(), ...dados };
199	  return ok({ ...estado, pagamentosFatura: [...estado.pagamentosFatura, pagamento] });
200	}
