86	/** Dá baixa: cria a transação real e liga o lançamento a ela. Recusa lançamentos já pagos. */
87	export function marcarComoPago(estado: AppState, id: string, dados: DadosBaixa): Resultado<AppState> {
88	  const item = estado.agenda.find((a) => a.id === id);
89	  if (!item) return falha('Lançamento não encontrado.');
90	  if (item.pagoEm) return falha('Este lançamento já foi pago.');
