114	/** Desfaz a baixa: remove a transação criada e volta o lançamento ao estado não pago. */
115	export function reabrirAgendamento(estado: AppState, id: string): Resultado<AppState> {
116	  const item = estado.agenda.find((a) => a.id === id);
