150	export function totaisAgenda(itens: Agendamento[]): TotaisAgenda {
151	  const t: TotaisAgenda = { aPagar: 0, aReceber: 0, jaPago: 0, jaRecebido: 0 };
152	  for (const a of itens) {
153	    const chave = a.tipo === 'despesa' ? (a.pagoEm ? 'jaPago' : 'aPagar') : a.pagoEm ? 'jaRecebido' : 'aReceber';
