169	/** Não pagos que vencem de hoje até `DIAS_ALERTA` dias à frente, e a contagem dos atrasados. */
170	export function alertaVencimentos(estado: AppState, hoje: DataISO): AlertaVencimentos {
171	  const limite = somarDias(hoje, DIAS_ALERTA);
172	  const abertos = estado.agenda.filter((a) => !a.pagoEm);
173	  const proximos = abertos
174	    .filter((a) => a.vencimento >= hoje && a.vencimento <= limite)
175	    .sort((a, b) => (a.vencimento < b.vencimento ? -1 : a.vencimento > b.vencimento ? 1 : a.criadoEm - b.criadoEm));
176	  return { proximos, atrasados: abertos.filter((a) => a.vencimento < hoje).length };
177	}
